import stylesText from './log-menu.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { showModalFresh } from '../../../../utils/dialog.js';
import { MEAL_TYPES, type LogWithLines, type MealType } from '@motivation/shared';
import { HEALTH_EVENTS, createLogActionEvent, type AmountChangeEvent, type LogMenuAction } from '../../health-events.js';
import '../amount-input/amount-input.component.js';
import type { AmountInput } from '../amount-input/amount-input.component.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
    <dialog class="sheet">
        <div class="title"><span class="name"></span><span class="meta"></span></div>
        <div class="panel" data-panel="main">
            <button type="button" class="item" data-go="edit">Edit</button>
            <button type="button" class="item" data-go="scale">Scale portion</button>
            <button type="button" class="item" data-go="move">Move to day / slot</button>
            <button type="button" class="item" data-go="save-as-meal">Save as meal</button>
            <button type="button" class="item danger" data-go="delete">Delete from day</button>
        </div>
        <div class="panel" data-panel="scale" hidden>
            <amount-input unit="factor" presets label="Portion"></amount-input>
            <button type="button" class="apply" data-apply="scale">Scale</button>
        </div>
        <div class="panel" data-panel="move" hidden>
            <label class="field"><span>Day</span><input class="move-date" type="date" required></label>
            <label class="field"><span>Slot</span><select class="move-slot">
                ${MEAL_TYPES.map((m) => `<option value="${m}">${m}</option>`).join('')}
            </select></label>
            <button type="button" class="apply" data-apply="move">Move</button>
        </div>
        <div class="panel" data-panel="save-as-meal" hidden>
            <label class="field"><span>Meal name</span><input class="meal-name" autocomplete="off"></label>
            <button type="button" class="apply" data-apply="save-as-meal">Save meal</button>
        </div>
        <div class="panel" data-panel="delete" hidden>
            <p class="confirm"></p>
            <button type="button" class="apply danger" data-apply="delete">Delete</button>
        </div>
        <button type="button" class="cancel">Cancel</button>
    </dialog>
`;

/**
 * Story 422 — a log's ⋯ menu on the day (418 #10): Edit, Scale, Move, Save as meal, Delete. The
 * choices that need a value get their own small panel, and Delete asks first. It writes
 * nothing: `health:log-action` carries the choice to the day screen.
 */
export class LogMenu extends HTMLElement {
    private logValue: LogWithLines | null = null;
    private factor = 1;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        customElements.upgrade(shadow);

        for (const b of shadow.querySelectorAll<HTMLButtonElement>('[data-go]')) {
            b.addEventListener('click', () => {
                const go = b.dataset.go!;
                if (go === 'edit') this.act({ kind: 'edit' });
                else this.show(go);
            });
        }
        (shadow.querySelector('amount-input') as AmountInput).addEventListener(HEALTH_EVENTS.AMOUNT_CHANGE, (e: AmountChangeEvent) => {
            e.stopPropagation();
            this.factor = e.detail.value;
        });
        for (const b of shadow.querySelectorAll<HTMLButtonElement>('[data-apply]')) {
            b.addEventListener('click', () => this.apply(b.dataset.apply!));
        }
        shadow.querySelector('.cancel')!.addEventListener('click', () => this.dialog.close());
    }

    /** Open on this log, at its main list. */
    open(log: LogWithLines): void {
        this.logValue = log;
        const shadow = this.shadowRoot!;
        const name = log.name ?? log.lines[0]?.food_name ?? 'Log';
        (shadow.querySelector('.name') as HTMLElement).textContent = name;
        (shadow.querySelector('.meta') as HTMLElement).textContent = `${log.meal_type} · ${log.lines.length} item${log.lines.length === 1 ? '' : 's'}`;
        (shadow.querySelector('.move-date') as HTMLInputElement).value = log.date;
        (shadow.querySelector('.move-slot') as HTMLSelectElement).value = log.meal_type;
        (shadow.querySelector('.meal-name') as HTMLInputElement).value = name;
        (shadow.querySelector('.confirm') as HTMLElement).textContent = `Delete ${name} from ${log.date}? Its lines go with it.`;
        this.factor = 1;
        (shadow.querySelector('amount-input') as AmountInput).value = 1;
        this.show('main');
        showModalFresh(this.dialog);
    }

    private get dialog(): HTMLDialogElement {
        return this.shadowRoot!.querySelector('dialog') as HTMLDialogElement;
    }

    private show(panel: string): void {
        for (const p of this.shadowRoot!.querySelectorAll<HTMLElement>('.panel')) p.hidden = p.dataset.panel !== panel;
    }

    private apply(kind: string): void {
        const shadow = this.shadowRoot!;
        if (kind === 'scale') {
            if (this.factor !== 1) this.act({ kind: 'scale', factor: this.factor });
            else this.dialog.close();
        } else if (kind === 'move') {
            const date = (shadow.querySelector('.move-date') as HTMLInputElement).value;
            if (!date) return;
            this.act({ kind: 'move', date, meal_type: (shadow.querySelector('.move-slot') as HTMLSelectElement).value as MealType });
        } else if (kind === 'save-as-meal') {
            const name = (shadow.querySelector('.meal-name') as HTMLInputElement).value.trim();
            if (!name) return;
            this.act({ kind: 'save-as-meal', name });
        } else if (kind === 'delete') {
            this.act({ kind: 'delete' });
        }
    }

    private act(action: LogMenuAction): void {
        const log = this.logValue;
        this.dialog.close();
        if (log) this.dispatchEvent(createLogActionEvent({ log_id: log.id, action }));
    }
}

if (!customElements.get('log-menu')) {
    customElements.define('log-menu', LogMenu);
}
