/** Story 258: a slot whose kcal exceed this share of the budget gets the ⚠. */
const SLOT_WARN_BUDGET_FRACTION = 0.5;
/** Story 430 (121's gesture): how long a press on a log picks it. */
const LONG_PRESS_MS = 500;

/**
 * Chronological sort key for a log (story 260): the eaten-at instant when stamped, otherwise
 * `created_at`. Both are stored timestamps (story 389), so one string compare orders a mixed list.
 */
function logSortInstant(log: LogWithLines): string {
    return log.consumed_at ?? log.created_at;
}

/** Each line's nutrition, from its snapshot (418 #4). */
function logNutrition(log: LogWithLines): LineNutrition[] {
    return log.lines.map((line) => viewNutrition(logLineView(line)));
}

/** Days-since figures per "deliberate" activity type (story 258, 3c widget). */
export interface LastActivityDays {
    weight_training: number | null;
    running: number | null;
    cycling: number | null;
}

export class HealthDayDetail extends HTMLElement {
    private _dateStr: string = '';
    private _activities: Activity[] = [];
    private _logs: LogWithLines[] = [];
    /** The multi-line logs open on screen, kept through a re-render. */
    private _openLogs = new Set<string>();
    /** Story 430: logs picked by a long-press, for Save as meal; empty is not selecting. */
    private _selected = new Set<string>();
    private _dayBurn: ActivityBurn | null = null;
    private _burnByActivityId: Map<string, ActivityBurn> = new Map();
    private _steps: number | null = null;
    private _activeTab: DayTab = DEFAULT_DAY_TAB;
    private unsubscribeTargets: (() => void) | null = null;

    connectedCallback(): void {
        // The hero bars, slot ⚠ and steps goal all scale against the targets,
        // which resolve asynchronously at boot (and can be edited from the
        // week widget) — re-render the target-dependent pieces when they land.
        this.unsubscribeTargets = healthTargetsService.onChange(() => {
            this.renderSummary();
            this.renderNutrition();
            this.renderSteps();
        });
    }

    disconnectedCallback(): void {
        this.unsubscribeTargets?.();
        this.unsubscribeTargets = null;
    }

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));

        shadow.getElementById('prev-btn')!.addEventListener('click', () => {
            if (!this._dateStr) return;
            const prevDay = Temporal.PlainDate.from(this._dateStr).subtract({ days: 1 }).toString();
            navigate(`/health/day/${prevDay}`, { history: 'replace' });
        });

        shadow.getElementById('next-btn')!.addEventListener('click', () => {
            if (!this._dateStr) return;
            const nextDay = Temporal.PlainDate.from(this._dateStr).add({ days: 1 }).toString();
            navigate(`/health/day/${nextDay}`, { history: 'replace' });
        });

        shadow.getElementById('add-workout-btn')!.addEventListener('click', () => {
            if (!this._dateStr) return;
            this.dispatchEvent(createAddWorkoutEvent({ date: this._dateStr }));
        });

        // Story 307: a workout missing from this day is noticed here, so the way
        // to fetch it is here too — the screen opens the sync dialog. The sync
        // itself is not day-scoped (it reconciles the bridge's whole 30-day
        // window); this is a shortcut to it, not a narrowing of it.
        shadow.getElementById('hc-sync-btn')!.addEventListener('click', () => {
            this.dispatchEvent(createHcSyncRequestEvent());
        });

        // Story 173/258: the header 💬 chip jumps to this day's briefing —
        // the note keyed by day D is the one written on the morning of D
        // looking ahead to it.
        shadow.getElementById('coach-chip')!.addEventListener('click', () => {
            if (!this._dateStr) return;
            navigate(`/health/coaching/${encodeURIComponent(this._dateStr)}`);
        });

        // Story 258: Activity | Nutrition tabs. Story 289 moved the choice into
        // the URL, so a user tap syncs it back (silently — see syncTabUrl).
        shadow.getElementById('tab-activity')!.addEventListener('click', () => this.selectTab('activity'));
        shadow.getElementById('tab-nutrition')!.addEventListener('click', () => this.selectTab('nutrition'));

        // A one-line log's row is its line: say which log it belongs to, as `<log-block>` does.
        shadow.getElementById('meal-sections')!.addEventListener(HEALTH_EVENTS.LINE_OPEN, (e: Event) => {
            const event = e as LineOpenEvent;
            if (event.detail.log_id !== undefined) return;
            const logId = (event.target as HTMLElement).dataset.logId;
            if (!logId) return;
            e.stopPropagation();
            this.dispatchEvent(createLineOpenEvent({ key: event.detail.key, log_id: logId }));
        });

        this.wireSelection();
        const mealSections = shadow.getElementById('meal-sections')!;
        for (const meal of MEAL_TYPES) {
            const section = document.createElement('day-meal-section');
            section.setAttribute('meal-type', meal);
            section.dataset.mealType = meal;
            const emptyState = document.createElement('div');
            emptyState.className = 'empty-state';
            emptyState.dataset.role = 'empty';
            emptyState.textContent = 'Nothing logged yet.';
            section.appendChild(emptyState);
            mealSections.appendChild(section);
        }

        // Listen on the host rather than the shadow root: `ShadowRoot`'s typed
        // event map only knows `slotchange`, so the typed CustomEvent listener
        // doesn't type-check against shadow.addEventListener. Same outcome at
        // runtime because `day-meal-section-add` bubbles + composed.
        this.addEventListener(HEALTH_EVENTS.DAY_MEAL_SECTION_ADD, (event: DayMealSectionAddEvent) => {
            if (!this._dateStr) return;
            this.dispatchEvent(createAddFoodEvent({ date: this._dateStr, meal: event.detail.meal }));
        });
    }

    set dateContext(val: string) {
        // Story 430: a selection belongs to the day it was made on.
        if (val !== this._dateStr) this.clearSelection();
        this._dateStr = val;
        this.shadowRoot!.getElementById('day-title')!.textContent = val;
    }

    get dateContext(): string {
        return this._dateStr;
    }

    set activities(data: Activity[]) {
        this._activities = data;
        this.renderWorkouts();
    }

    /**
     * The day's logs (story 422). Each line carries its own name, unit, photo and nutrition
     * (421's snapshot), so the day fetches nothing else to draw them. The Activity pane's ghost
     * stubs (story 260) derive from them too.
     */
    set logs(data: LogWithLines[]) {
        this._logs = data;
        this.renderNutrition();
        this.renderSummary();
        this.renderWorkouts();
    }

    get logs(): LogWithLines[] {
        return this._logs;
    }

    /** Day burn (real-or-estimated), story 258 — feeds the hero and the burn row. */
    set dayBurn(data: ActivityBurn | null) {
        this._dayBurn = data;
        this.renderSummary();
        this.renderDayBurnRow();
    }

    /** Per-activity burn for the workout cards' `~N kcal` fallback (story 258). */
    set burnByActivityId(data: Map<string, ActivityBurn>) {
        this._burnByActivityId = data;
        this.renderWorkouts();
    }

    /** Steps recorded for this day, or null when there is no row (story 258). */
    set steps(value: number | null) {
        this._steps = value;
        this.renderSteps();
    }

    private renderSteps(): void {
        const shadow = this.shadowRoot!;
        const row = shadow.getElementById('steps-row')!;
        if (this._steps === null) {
            row.hidden = true;
            return;
        }
        const goal = getHealthTargets().step_goal;
        shadow.getElementById('steps-fill')!.style.width = `${Math.min(this._steps / goal, 1) * 100}%`;
        shadow.getElementById('steps-label')!.textContent = `${formatSteps(this._steps)} / ${formatSteps(goal)}`;
        row.hidden = false;
    }

    /** "Time since" per deliberate activity type, relative to the viewed day. */
    set lastActivityDays(value: LastActivityDays) {
        const row = this.shadowRoot!.getElementById('since-row')!;
        row.replaceChildren();
        const entries: Array<[string, number | null]> = [
            ['🏋️', value.weight_training],
            ['🏃', value.running],
            ['🚴', value.cycling],
        ];
        for (const [icon, days] of entries) {
            const span = document.createElement('span');
            span.className = 'since-item';
            span.textContent = days === null ? `${icon} —` : days === 0 ? `${icon} today ✓` : `${icon} ${days}d ago`;
            row.appendChild(span);
        }
    }

    /**
     * Story 289: which half of the day is showing. Set by the screen from the
     * `?tab=` param on mount — that path does not sync the URL back, because
     * the URL is where the value came from.
     */
    set activeTab(tab: DayTab) {
        this.setActiveTab(tab);
    }

    get activeTab(): DayTab {
        return this._activeTab;
    }

    /** A user picking a tab: show it, and make the URL say so. */
    private selectTab(tab: DayTab): void {
        this.setActiveTab(tab);
        this.syncTabUrl(tab);
    }

    private setActiveTab(tab: DayTab): void {
        this._activeTab = tab;
        const shadow = this.shadowRoot!;
        const activity = tab === 'activity';
        shadow.getElementById('activity-pane')!.hidden = !activity;
        shadow.getElementById('nutrition-pane')!.hidden = activity;
        shadow.getElementById('tab-activity')!.classList.toggle('is-active', activity);
        shadow.getElementById('tab-activity')!.setAttribute('aria-selected', String(activity));
        shadow.getElementById('tab-nutrition')!.classList.toggle('is-active', !activity);
        shadow.getElementById('tab-nutrition')!.setAttribute('aria-selected', String(!activity));
    }

    /**
     * Keep the URL honest about the visible tab so a reload or a re-entry from
     * the timeline lands where you were. `silent` so the router rewrites the
     * URL without re-activating the route — a plain replace would remount the
     * screen and refetch the whole day on every tab tap (story 289).
     */
    private syncTabUrl(tab: DayTab): void {
        if (!this._dateStr) return;
        const path = `/health/day/${encodeURIComponent(this._dateStr)}`;
        navigate(tab === 'activity' ? `${path}?tab=activity` : path, { history: 'replace', silent: true });
    }

    private renderDayBurnRow(): void {
        const shadow = this.shadowRoot!;
        const row = shadow.getElementById('day-burn-row')!;
        if (!this._dayBurn || this._dayBurn.kcal <= 0) {
            row.hidden = true;
            return;
        }
        shadow.getElementById('day-burn-total')!.textContent =
            `${this._dayBurn.estimated ? '~' : ''}${formatMacro(this._dayBurn.kcal)} kcal`;
        row.hidden = false;
    }

    showLoading() {
        const shadow = this.shadowRoot!;
        shadow.getElementById('loading')!.hidden = false;
        shadow.getElementById('content')!.hidden = true;
        shadow.getElementById('error')!.hidden = true;
    }

    hideLoading() {
        this.shadowRoot!.getElementById('loading')!.hidden = true;
    }

    showError(message: string) {
        const shadow = this.shadowRoot!;
        const el = shadow.getElementById('error')!;
        el.textContent = message;
        el.hidden = false;
        shadow.getElementById('loading')!.hidden = true;
    }

    showContent() {
        this.shadowRoot!.getElementById('content')!.hidden = false;
        this.refreshHcLastSynced();
    }

    /**
     * Story 307: how stale the Activity tab's Health Connect data is. The screen
     * calls this again when the sync dialog closes, so a sync that changed
     * nothing still updates the caption that says a sync happened.
     */
    refreshHcLastSynced(): void {
        this.shadowRoot!.getElementById('hc-sync-last')!.textContent = hcLastSyncedLabel();
    }

    private renderSummary() {
        const shadow = this.shadowRoot!;
        // Story 368: a total with a line that does not know a value reads "1250+?", never 0-padded.
        const totals = totalsOf(this._logs.flatMap(logNutrition));
        const cal = totals.calories.value ?? 0;
        const p = totals.protein_g.value ?? 0;
        shadow.getElementById('total-cal')!.textContent = this._logs.length === 0 ? '0' : formatTotal(totals.calories);
        shadow.getElementById('total-p')!.textContent = this._logs.length === 0 ? '0' : formatTotal(totals.protein_g);
        shadow.getElementById('total-c')!.textContent = this._logs.length === 0 ? '0' : formatTotal(totals.carbs_g);
        shadow.getElementById('total-fat')!.textContent = this._logs.length === 0 ? '0' : formatTotal(totals.fat_g);
        shadow.getElementById('total-fib')!.textContent = this._logs.length === 0 ? '0' : formatTotal(totals.fiber_g);

        // Story 258 hero: burn credit stretches the allowance past the budget;
        // the tick marks the budget itself. Judged on net (eaten − burn).
        const targets = getHealthTargets();
        const budget = targets.calorie_budget_kcal;
        const burn = this._dayBurn?.kcal ?? 0;
        const burnPrefix = this._dayBurn?.estimated ? '~' : '';
        const net = cal - burn;

        const burnEl = shadow.getElementById('hero-burn')!;
        const netEl = shadow.getElementById('hero-net')!;
        if (burn > 0) {
            burnEl.textContent = `🔥 −${burnPrefix}${formatMacro(burn)}`;
            netEl.textContent = `net ${burnPrefix}${formatMacro(net)}`;
            burnEl.hidden = false;
            netEl.hidden = false;
        } else {
            burnEl.hidden = true;
            netEl.hidden = true;
        }

        const allowance = budget + burn;
        const scale = Math.max(cal, allowance, 1);
        shadow.getElementById('hero-kcal-fill')!.style.width = `${(cal / scale) * 100}%`;
        const credit = shadow.getElementById('hero-burn-credit')!;
        if (burn > 0) {
            credit.style.left = `${(budget / scale) * 100}%`;
            credit.style.width = `${(burn / scale) * 100}%`;
            credit.hidden = false;
        } else {
            credit.hidden = true;
        }
        shadow.getElementById('hero-budget-tick')!.style.left = `${(budget / scale) * 100}%`;
        const kcalLabel = shadow.getElementById('hero-kcal-label')!;
        const over = net - budget;
        kcalLabel.textContent = over > 0 ? `+${formatMacro(over)} over` : 'under ✓';
        kcalLabel.classList.toggle('is-over', over > 0);

        shadow.getElementById('hero-protein-fill')!.style.width =
            `${Math.min(p / targets.protein_target_g, 1) * 100}%`;
        shadow.getElementById('protein-target')!.textContent = formatMacro(targets.protein_target_g);
    }

    private renderWorkouts() {
        const container = this.shadowRoot!.getElementById('workouts-list')!;
        container.replaceChildren();
        if (this._activities.length === 0) {
            const emptyState = document.createElement('div');
            emptyState.className = 'empty-state';
            emptyState.textContent = 'No workouts logged.';
            container.appendChild(emptyState);
        }

        // Walks are Fit auto-detections, not the workouts this list is for
        // (story 254): several on one day fold into a collapsed <details>
        // group; the individual cards inside stay clickable. Real workouts
        // render first.
        const walks = this._activities.filter((a) => a.type === 'walking');
        const rest = this._activities.filter((a) => a.type !== 'walking');

        for (const act of rest) {
            container.appendChild(this.buildActivityCard(act));
        }

        if (walks.length === 1) {
            container.appendChild(this.buildActivityCard(walks[0]));
        } else if (walks.length > 1) {
            const group = document.createElement('details');
            group.className = 'walks-group';
            const summary = document.createElement('summary');
            const total = walks.reduce((sum, walk) => sum + (walk.duration_minutes ?? 0), 0);
            summary.textContent = `${activityIcon('walking')} ${walks.length} walks · ${formatDurationMinutes(total)}`;
            group.appendChild(summary);
            for (const act of walks) {
                group.appendChild(this.buildActivityCard(act));
            }
            container.appendChild(group);
        }

        // Story 260 (3b/3c wireframes): stamped meals ghost through into the
        // Activity feed, ordered by eaten-at time. Unstamped days add nothing.
        const stubs = this.buildMealStubs();
        if (stubs) container.appendChild(stubs);
    }

    /**
     * Cross-tab ghost stubs (story 260): one subdued row per stamped log, ordered by time.
     * Clicking one jumps to the Nutrition tab. Returns null when the day has no stamped
     * logs — no stubs, no container.
     */
    private buildMealStubs(): HTMLElement | null {
        const items = this._logs
            .filter((l): l is LogWithLines & { consumed_at: string } => l.consumed_at !== null)
            .map((l) => ({
                instant: l.consumed_at,
                name: l.name ?? l.lines[0]?.food_name ?? `${l.meal_type} meal`,
                kcal: formatTotal(totalsOf(logNutrition(l)).calories),
            }))
            .sort((a, b) => a.instant.localeCompare(b.instant));
        if (items.length === 0) return null;

        const list = document.createElement('div');
        list.className = 'meal-stubs';
        for (const item of items) {
            const stub = document.createElement('button');
            stub.type = 'button';
            stub.className = 'meal-stub';
            const time = document.createElement('span');
            time.className = 'food-time';
            time.textContent = instantToHHMM(item.instant, getAppTimeZone());
            const name = document.createElement('span');
            name.className = 'meal-stub-name';
            name.textContent = `🍽 ${item.name}`;
            const kcal = document.createElement('span');
            kcal.className = 'meal-stub-kcal';
            kcal.textContent = `${item.kcal} kcal`;
            stub.append(time, name, kcal);
            stub.addEventListener('click', () => this.selectTab('nutrition'));
            list.appendChild(stub);
        }
        return list;
    }

    private buildActivityCard(act: Activity): ActivityDetailCard {
        const card = document.createElement('activity-detail-card') as ActivityDetailCard;
        card.activity = act;
        // Story 258: MET estimate fallback for rows without recorded energy.
        const burn = this._burnByActivityId.get(act.id);
        card.estimatedBurnKcal = burn?.estimated ? burn.kcal : null;
        // A calendar class that has not been adopted is re-materialized live and has no DB row, so
        // there is nothing to open — it gets the adopt button instead (story 323). Everything else,
        // adopted classes included, is clickable and the hub shows source-appropriate affordances.
        if (isSynthesizedCalendarEvent(act)) {
            // Story 371: the card holds its button until the screen's adopt settles.
            card.onAdopt = (event) => dispatchAndSettle(this, createAdoptCalendarActivityEvent({ activity: event }));
        } else {
            card.style.cursor = 'pointer';
            card.addEventListener('click', () => {
                this.dispatchEvent(createEditWorkoutEvent({ activity: act }));
            });
        }
        return card;
    }

    private renderNutrition() {
        const shadow = this.shadowRoot!;
        // A block left open stays open through a re-render (a scale, a move, a targets change).
        this._openLogs = new Set([...shadow.querySelectorAll<HTMLElement>('log-block[open]')].map((b) => b.dataset.logId!));
        for (const meal of MEAL_TYPES) {
            const section = shadow.querySelector(`day-meal-section[data-meal-type="${meal}"]`) as HTMLElement | null;
            if (!section) continue;
            section.replaceChildren();

            // Story 260: chronological within the slot — by eaten-at, else when it was logged.
            const logs = this._logs
                .filter((l) => l.meal_type === meal)
                .sort((a, b) => logSortInstant(a).localeCompare(logSortInstant(b)));

            // Story 258: slot total in the divider header; a slot eating more
            // than half the budget gets the ⚠ treatment.
            const total = totalsOf(logs.flatMap(logNutrition)).calories;
            if (logs.length > 0) {
                section.setAttribute('total-kcal', formatTotal(total));
                section.toggleAttribute('over', (total.value ?? 0) > getHealthTargets().calorie_budget_kcal * SLOT_WARN_BUDGET_FRACTION);
            } else {
                section.removeAttribute('total-kcal');
                section.removeAttribute('over');
            }

            if (logs.length === 0) {
                const emptyState = document.createElement('div');
                emptyState.className = 'empty-state';
                emptyState.textContent = 'Nothing logged yet.';
                section.appendChild(emptyState);
                continue;
            }

            // 418 #10: a one-line log is a plain row; a log of several lines a collapsed block.
            for (const log of logs) section.appendChild(this.buildLog(log));
        }
        this.renderSelection();
    }

    // ── Story 430: several logs saved as one meal ────────────────────────

    /** A long press picks a log; while picking, a tap adds or removes one and opens nothing. */
    private wireSelection(): void {
        const shadow = this.shadowRoot!;
        const sections = shadow.getElementById('meal-sections')!;
        const logOf = (e: Event) => (e.composedPath().find((n) => n instanceof HTMLElement && n.dataset.logId) as HTMLElement | undefined)?.dataset.logId ?? null;
        let timer: ReturnType<typeof setTimeout> | null = null;
        let start: { x: number; y: number } | null = null;
        let pressed = false;
        const cancel = () => { if (timer) clearTimeout(timer); timer = null; start = null; };
        sections.addEventListener('pointerdown', (e: PointerEvent) => {
            // A new press: the last one's swallowed click, if it never came, is not this one's.
            pressed = false;
            const logId = logOf(e);
            if (!logId || this._selected.size > 0) return;
            start = { x: e.clientX, y: e.clientY };
            timer = setTimeout(() => {
                timer = null;
                pressed = true;
                this.toggleSelected(logId);
            }, LONG_PRESS_MS);
        });
        sections.addEventListener('pointermove', (e: PointerEvent) => {
            if (start && Math.hypot(e.clientX - start.x, e.clientY - start.y) > 10) cancel();
        });
        for (const type of ['pointerup', 'pointercancel', 'pointerleave']) sections.addEventListener(type, cancel);
        // The press's own context menu / callout is the gesture, not a menu.
        sections.addEventListener('contextmenu', (e) => { if (logOf(e)) e.preventDefault(); });
        // Capture: the row's own tap (open the line, the ⋯ menu) never runs while picking.
        sections.addEventListener('click', (e) => {
            if (pressed) {
                pressed = false;
                e.preventDefault();
                e.stopPropagation();
                return;
            }
            if (this._selected.size === 0) return;
            const logId = logOf(e);
            if (!logId) return;
            e.preventDefault();
            e.stopPropagation();
            this.toggleSelected(logId);
        }, { capture: true });
        shadow.getElementById('selection-cancel')!.addEventListener('click', () => this.clearSelection());
        shadow.getElementById('selection-save')!.addEventListener('click', () => {
            // Day order: the slots top to bottom, chronological within each — as the day shows them.
            const order = [...shadow.querySelectorAll<HTMLElement>('day-meal-section > [data-log-id]')].map((el) => el.dataset.logId!);
            this.dispatchEvent(createSaveLogsAsMealEvent({ log_ids: order.filter((id) => this._selected.has(id)) }));
        });
    }

    private toggleSelected(logId: string): void {
        if (this._selected.has(logId)) this._selected.delete(logId);
        else this._selected.add(logId);
        this.renderSelection();
    }

    clearSelection(): void {
        this._selected.clear();
        this.renderSelection();
    }

    private renderSelection(): void {
        const shadow = this.shadowRoot!;
        // A log gone from the day (deleted, moved) is no longer picked.
        const present = new Set(this._logs.map((l) => l.id));
        for (const id of this._selected) if (!present.has(id)) this._selected.delete(id);
        for (const el of shadow.querySelectorAll<HTMLElement>('day-meal-section > [data-log-id]')) {
            el.toggleAttribute('selected', this._selected.has(el.dataset.logId!));
        }
        const n = this._selected.size;
        this.classList.toggle('selection-mode', n > 0);
        (shadow.getElementById('selection-toolbar') as HTMLElement).hidden = n === 0;
        shadow.getElementById('selection-count')!.textContent = `${n} selected`;
    }

    private buildLog(log: LogWithLines): HTMLElement {
        const time = log.consumed_at ? instantToHHMM(log.consumed_at, getAppTimeZone()) : null;
        if (log.lines.length === 1) {
            const row = document.createElement('line-row') as LineRow;
            row.dataset.logId = log.id;
            if (time) row.setAttribute('time', time);
            row.line = logLineView(log.lines[0]);
            return row;
        }
        const block = document.createElement('log-block') as LogBlock;
        block.dataset.logId = log.id;
        if (time) block.setAttribute('time', time);
        if (this._openLogs.has(log.id)) block.setAttribute('open', '');
        block.log = log;
        return block;
    }

}

if (!customElements.get('health-day-detail')) {
    customElements.define('health-day-detail', HealthDayDetail);
}
